insert into bottleneck_signatures (id, name, description, detection_rule, default_severity, source_reference) values (gen_random_uuid(), 'congestion', 'Congestion score climbs (SSD/cache-tier write buffer, log space, or memory heap) while write IOPS drop and write latency rises — vSAN''s own flow-control throttling writes at the front door before it cascades downstream.', '{"signals": ["congestion_pct", "cache_tier_usage_pct", "iops_write", "write_latency_ms"], "logic": "congestion_pct AND cache_tier_usage_pct trending up, iops_write trending down"}'::jsonb, 'warning', 'Broadcom KB 326479 ''Understanding Congestion in vSAN''; KB 327050 ''vSAN memory or SSD congestion reached threshold limit''');
insert into bottleneck_signatures (id, name, description, detection_rule, default_severity, source_reference) values (gen_random_uuid(), 'capacity_utilization', 'Used capacity crosses documented vSAN Health Service thresholds: Yellow at 70%, Red at 90%. Past Red, vSAN has limited functionality — storage vMotion, VM creation/power-on, and snapshot operations start failing.', '{"signals": ["used_capacity_pct"], "logic": "used_capacity_pct >= 70 -> warning, >= 90 -> critical"}'::jsonb, 'critical', 'Broadcom KB 326889 ''vSAN Health Service - Capacity utilization''');
insert into bottleneck_signatures (id, name, description, detection_rule, default_severity, source_reference) values (gen_random_uuid(), 'resync_storm_post_maintenance', 'Resync backlog spikes immediately after a host exits Maintenance Mode (delta-sync of components that went stale under ''Ensure accessibility''). Usually benign in small (3-4 node) clusters — the tell is whether the backlog is steadily draining (expected) or flat/growing (investigate as a real fault).', '{"signals": ["resync_backlog_gb"], "logic": "resync_backlog_gb spikes after maintenance-mode exit; classify by whether it is draining"}'::jsonb, 'warning', 'Broadcom KB 438821 ''vSAN massive resync and degraded object health alerts after exiting Maintenance Mode''');
insert into bottleneck_signatures (id, name, description, detection_rule, default_severity, source_reference) values (gen_random_uuid(), 'network_latency', 'Inter-host ping latency exceeds vSAN''s documented 5ms warning threshold — vSAN performance depends on low, consistent latency between hosts, so this points at a NIC, switch, or uplink problem before it shows up as I/O latency.', '{"signals": ["network_latency_ms"], "logic": "network_latency_ms > 5 sustained"}'::jsonb, 'warning', 'Broadcom KB 315544 ''vSAN Health Service - Network Health - Network Latency Check''');
insert into bottleneck_signatures (id, name, description, detection_rule, default_severity, source_reference) values (gen_random_uuid(), 'host_component_limit', 'A host''s component count approaches the per-host ceiling (9,000 on OSA). Green <80%, Yellow 80-90%, Red >90%. Past Red, new VM deployment and rebuild operations fail outright — this is a hard capacity wall, not a soft one.', '{"signals": ["component_count_pct"], "logic": "component_count_pct >= 80 -> warning, >= 90 -> critical"}'::jsonb, 'critical', 'Broadcom KB 315533 ''vSAN Health Service - Limits - Host component''; KB 315507 ''vSAN Component Limit per Cluster''');
